                "doc.baselines.th_stroke": "Corsa (Camma)",
                "doc.baselines.th_lining": "Riferimento Linee",
                "doc.baselines.th_shading": "Riferimento Sfumature",
                "doc.baselines.th_packing": "Riferimento Riempimento",
                "doc.baselines.rotary_name": "Rotativa (Pen / Slider / Direct)",
                "doc.baselines.coil_name": "Bobine (Armatura)",
                "doc.baselines.stroke_25": "2,5 mm (Corta)",
                "doc.baselines.stroke_30": "3,0 mm (Corta-Media)",
                "doc.baselines.stroke_35": "3,5 mm (Media)",
                "doc.baselines.stroke_40": "4,0 mm (Lunga)",
                "doc.baselines.stroke_45": "4,5 mm (Pesante)",
                "doc.baselines.stroke_coil_35": "3,5 mm (Corsa Standard)",
                "doc.baselines.stroke_coil_40": "4,0 mm (Lunga)",
                "doc.tuning.title": "Regolazione su Pelle Sintetica",
                "doc.tuning.step1_title": "Ascolta il Suono del Motore:",
                "doc.tuning.step1_body": "Un motore rotativo efficiente emette un ronzio a frequenza costante. Se il motore flette, esita o abbassa la tonalità quando tocca la pelle, sta faticando contro la membrana della cartuccia o l'attrito dell'ago. Se strilla con un fischio acuto, sta girando troppo velocemente.",
                "doc.tuning.step2_title": "Ispeziona il Rilascio del Tratto:",
                "doc.tuning.step2_body": "Il tratto deve depositare il colore uniformemente con un movimento continuo. Se l'ago perde colpi o si impunta, valuta se la corsa o il voltaggio necessitano di un aumento di 0,2 V – 0,4 V. Per le sfumature, cerca una stesura pulita di micropunti anziché abrasioni cutanee.",
                "doc.tuning.step3_title": "Modifica per Piccole Variazioni:",
                "doc.tuning.step3_body": "Non variare mai per salti di un volt completo. Regola con incrementi di 0,2 V – 0,5 V ed esegui più passate di prova prima di correggere ancora.",
                "doc.coil.title": "Sequenza di Regolazione Meccanica per Bobine",
                "doc.coil.intro": "Nelle macchine elettromagnetiche tradizionali, il voltaggio modula unicamente l'intensità del campo magnetico nei nuclei delle bobine. La frequenza di ciclo e la qualità della battuta sono determinate dalla geometria meccanica:",
                "doc.coil.step1_title": "Allineamento Meccanico:",
                "doc.coil.step1_body": "Assicurati che armatura, gommino e barra dell'ago siano perfettamente diritti senza creare attriti interni nel puntale.",
                "doc.coil.step2_title": "Spazio della Vite di Contatto:",
                "doc.coil.step2_body": "Imposta la distanza dei contatti prima di erogare corrente (regola empirica da studio: circa lo spessore di una moneta americana da 10 centesimi, 1,35 mm, per i liner e di una da 5 centesimi, 1,95 mm, per gli shader).",
                "doc.coil.step3_title": "Rigidità e Tensione delle Molle:",
                "doc.coil.step3_body": "Piega e regola l'angolo della molla posteriore per tarare la velocità di ritorno dell'armatura prima di intervenire sul voltaggio.",
                "doc.coil.step4_title": "Regolazione Accurata della Tensione:",
                "doc.coil.step4_body": "Intervieni sulla manopola dell'alimentatore unicamente dopo aver bilanciato meccanica e molle.",
                "doc.coil.notice_title": "Importante:",
                "doc.coil.notice_body": "Aumentare il voltaggio su una bobina non regolata non potrà mai rimediare a molle snervate, contatti usurati o condensatori non idonei. Sovralimentare bobine non tarate causa archi elettrici violenti, surriscaldamento e rapida distruzione delle viti di contatto.",
                "doc.wireless.title": "Comportamento dei Pacchi Batteria Wireless",
                "doc.wireless.sag_title": "Calo di Tensione Sotto Sforzo (Voltage Sag):",
                "doc.wireless.sag_body": "I pacchi wireless compatti utilizzano convertitori DC-DC interni. Sotto carico pesante, la loro effettiva potenza in uscita può scendere al di sotto del valore visualizzato, solitamente più di un alimentatore da banco.",
                "doc.wireless.jump_title": "Impulso di Avviamento Rapido (Jumpstart):",
                "doc.wireless.jump_body": "Alcuni motori rotativi richiedono un breve impulso di avvio per superare la resistenza della membrana della cartuccia da fermi. Se il tuo motore fatica ad avviarsi a bassi voltaggi, verifica se il tuo pacco o alimentatore è dotato di una funzione di jumpstart.",
                "doc.wireless.flutter_title": "Oscillazioni a Batteria Scarica:",
                "doc.wireless.flutter_body": "Quando la batteria si scarica, alcuni pacchi economici forniscono un'uscita meno stabile. Tieni una batteria di riserva carica e sostituisci quella principale prima che si scarichi.",
                "doc.tools.title": "Altri Strumenti per Studi Correlati",
                "doc.tools.intro": "Poli International sviluppa e pubblica strumenti gratuiti e open source per tatuatori, piercer e gestori di studi:",
                "doc.tools.needle": "Selettore Aghi",
                "doc.tools.needle_desc": "- Guida alla scelta di configurazioni, conicità (taper) e gruppi di aghi",
                "doc.tools.power": "Guida Risoluzione Problemi Alimentatori",
                "doc.tools.power_desc": "- Procedura di diagnosi per cali di tensione, interruzioni anomale e cortocircuiti nei cavi",
                "doc.tools.logbook": "Registro di Manutenzione Macchinette",
                "doc.tools.logbook_desc": "- Intervalli di assistenza, lubrificazione, sostituzione molle e revisione motori",
                "doc.tools.all": "Tutti gli Strumenti Gratuiti per Studi",
                "doc.tools.all_desc": "- Suite completa di calcolatori e prontuari tecnici per studi professionali",
                "doc.back_link": "Torna al Configuratore"
